void sha256(const uint8_t *data, size_t len, uint8_t out[32]) {
    /* Initial state in ABEF / CDGH form.
       Intel: state0 = ABEF = A,B,E,F ; state1 = CDGH = C,D,G,H
       _mm_set_epi32(lane3, lane2, lane1, lane0)
    */
    uint32_t H0 = 0x6a09e667, H1 = 0xbb67ae85, H2 = 0x3c6ef372, H3 = 0xa54ff53a;
    uint32_t H4 = 0x510e527f, H5 = 0x9b05688c, H6 = 0x1f83d9ab, H7 = 0x5be0cd19;

    __m128i state0 = _mm_set_epi32(H5, H4, H1, H0); /* F? wait: lane3=H5=F, lane2=H4=E, lane1=H1=B, lane0=H0=A => ABEF if lanes are A,B,E,F */
    __m128i state1 = _mm_set_epi32(H7, H6, H3, H2); /* lane3=H, lane2=G, lane1=D, lane0=C => CDGH */

    size_t off = 0;
    while (len - off >= 64) {
        sha256_compress(&state0, &state1, data + off);
        off += 64;
    }

    /* padding */
    uint8_t block[128];
    size_t rem = len - off;
    memcpy(block, data + off, rem);
    block[rem] = 0x80;
    size_t pad_len;
    if (rem < 56) {
        memset(block + rem + 1, 0, 55 - rem);
        pad_len = 64;
    } else {
        memset(block + rem + 1, 0, 119 - rem);
        pad_len = 128;
    }
    uint64_t bits = (uint64_t)len * 8;
    for (int i = 0; i < 8; i++)
        block[pad_len - 1 - i] = (uint8_t)(bits >> (8 * i));

    sha256_compress(&state0, &state1, block);
    if (pad_len == 128)
        sha256_compress(&state0, &state1, block + 64);

    /* Extract state. state0 lanes: A B E F, state1: C D G H */
    uint32_t abef[4], cdgh[4];
    _mm_storeu_si128((__m128i*)abef, state0);
    _mm_storeu_si128((__m128i*)cdgh, state1);
    uint32_t H[8] = {abef[0], abef[1], cdgh[0], cdgh[1], abef[2], abef[3], cdgh[2], cdgh[3]};
    for (int i = 0; i < 8; i++) {
        out[i*4+0] = (uint8_t)(H[i] >> 24);
        out[i*4+1] = (uint8_t)(H[i] >> 16);
        out[i*4+2] = (uint8_t)(H[i] >> 8);
        out[i*4+3] = (uint8_t)(H[i]);
    }
}

static void hex(const uint8_t *p, int n) {
    for (int i = 0; i < n; i++) printf("%02x", p[i]);
    printf("\n");
}

int main(int argc, char **argv) {
    uint8_t out[32];
    const char *s = "";
    sha256((const uint8_t*)s, 0, out);
    printf("empty: "); hex(out, 32);

    s = "abc";
    sha256((const uint8_t*)s, 3, out);
    printf("abc:   "); hex(out, 32);

    /* 56 bytes to test two-block padding */
    uint8_t buf[100];
    memset(buf, 'a', 56);
    sha256(buf, 56, out);
    printf("56a:   "); hex(out, 32);
    memset(buf, 'a', 64);
    sha256(buf, 64, out);
    printf("64a:   "); hex(out, 32);
    memset(buf, 'a', 100);
    sha256(buf, 100, out);
    printf("100a:  "); hex(out, 32);

    if (argc > 1 && strcmp(argv[1], "bench") == 0) {
        size_t n = 20000 * 1024;
        uint8_t *data = malloc(n);
        memset(data, 0x5a, n);
        /* warmup */
        sha256(data, n, out);
        struct timespec t0, t1;
        int iters = 20;
        clock_gettime(CLOCK_MONOTONIC, &t0);
        for (int i = 0; i < iters; i++) sha256(data, n, out);
        clock_gettime(CLOCK_MONOTONIC, &t1);
        double ms = (t1.tv_sec - t0.tv_sec) * 1000.0 + (t1.tv_nsec - t0.tv_nsec) / 1e6;
        printf("bench: %.2f ms/hash  (%.1f MB/s)\n", ms/iters, (n * iters / 1e6) / (ms/1000.0));
        hex(out, 32);
        free(data);
    }
    return 0;
}
