    uint8_t block[128];
    size_t rem=len-off;
    memcpy(block, data+off, rem);
    block[rem]=0x80;
    size_t pad_len = (rem<56)?64:128;
    memset(block+rem+1, 0, pad_len-rem-1-8);
    uint64_t bits=(uint64_t)len*8;
    for (int i=0;i<8;i++) block[pad_len-1-i]=(uint8_t)(bits>>(8*i));
    compress(s, block);
    if (pad_len==128) compress(s, block+64);
    for (int i=0;i<8;i++) {
        out[4*i]=s[i]>>24; out[4*i+1]=s[i]>>16; out[4*i+2]=s[i]>>8; out[4*i+3]=s[i];
    }
