static PyObject *py_bench(PyObject *self, PyObject *args) {
    Py_buffer buf; int which;
    if (!PyArg_ParseTuple(args, "y*i", &buf, &which)) return NULL;
    uint8_t out[32];
    /* release gil and time externally */
    Py_BEGIN_ALLOW_THREADS
    if (which==0) sha256_openssl(buf.buf, buf.len, out);
    else sha256_ours(buf.buf, buf.len, out);
    Py_END_ALLOW_THREADS
    PyObject *r = PyBytes_FromStringAndSize((char*)out, 32);
    PyBuffer_Release(&buf);
    return r;
}

/* 4 parallel independent hashes via threads using openssl, just to measure thread scaling of our process */
typedef struct { const uint8_t *data; size_t len; uint8_t out[32]; } job_t;
static void *job_fn(void *p) {
    job_t *j = p;
    SHA256(j->data, j->len, j->out);
    return NULL;
}
static PyObject *py_bench_threads(PyObject *self, PyObject *args) {
    Py_buffer buf; int nthreads;
    if (!PyArg_ParseTuple(args, "y*i", &buf, &nthreads)) return NULL;
    job_t *jobs = calloc(nthreads, sizeof(job_t));
    pthread_t *ts = calloc(nthreads, sizeof(pthread_t));
    Py_BEGIN_ALLOW_THREADS
    for (int i=0;i<nthreads;i++) {
        jobs[i].data = buf.buf; jobs[i].len = buf.len;
        pthread_create(&ts[i], NULL, job_fn, &jobs[i]);
    }
    for (int i=0;i<nthreads;i++) pthread_join(ts[i], NULL);
    Py_END_ALLOW_THREADS
    PyObject *r = PyBytes_FromStringAndSize((char*)jobs[0].out, 32);
    free(jobs); free(ts);
    PyBuffer_Release(&buf);
    return r;
}

