    {"hash", py_bench, METH_VARARGS, ""},
    {"hash_threads", py_bench_threads, METH_VARARGS, ""},
    {NULL, NULL, 0, NULL}
};
static struct PyModuleDef moduledef = {PyModuleDef_HEAD_INIT, "sha_ext", NULL, -1, methods};
PyMODINIT_FUNC PyInit_sha_ext(void){ return PyModule_Create(&moduledef); }
