    for (int i=0;i<8;i++){ out[4*i]=s[i]>>24; out[4*i+1]=s[i]>>16; out[4*i+2]=s[i]>>8; out[4*i+3]=s[i]; }
}

static double now(){ struct timespec t; clock_gettime(CLOCK_MONOTONIC,&t); return t.tv_sec + t.tv_nsec/1e9; }

int main(){
    size_t n = 20000ul*1024;
    uint8_t *data = aligned_alloc(64, n);
    memset(data, 0x5a, n);
    uint8_t out[32], ref[32];
    SHA256(data, n, ref);

    hash_with(compress, data, n, out);
    printf("scalar match %d\n", memcmp(out, ref, 32)==0);
    hash_with(compress_sse, data, n, out);
    printf("sse match %d\n", memcmp(out, ref, 32)==0);
    hash_ossl_block(data, n, out);
    printf("osslblock match %d\n", memcmp(out, ref, 32)==0);

    int iters = 8;
    double t0, t1;
    t0 = now(); for(int i=0;i<iters;i++) hash_with(compress, data, n, out); t1=now();
    printf("scalar unrolled: %.2f ms\n", (t1-t0)/iters*1000);
    t0 = now(); for(int i=0;i<iters;i++) hash_with(compress_sse, data, n, out); t1=now();
    printf("sse schedule:    %.2f ms\n", (t1-t0)/iters*1000);
    t0 = now(); for(int i=0;i<iters;i++) hash_ossl_block(data, n, out); t1=now();
    printf("ossl block:      %.2f ms\n", (t1-t0)/iters*1000);
    t0 = now(); for(int i=0;i<iters;i++) SHA256(data, n, out); t1=now();
    printf("SHA256():        %.2f ms\n", (t1-t0)/iters*1000);
    free(data);
    return 0;
}
