#   movdqu -0x80(%rdi) after adding 0x80, so first 16 bytes = one xmm = 4 lanes of one state word? 
#   It loads 8 xmm registers (128 bytes) = 8 state words x 4 lanes. Interleaved by word: 
#     xmm = [A0, A1, A2, A3] then [B0,B1,B2,B3] ... 
#   rsi = pointer to array of {ptr, int count} ? 
#     movq (%rsi), %r8      ; ptr0
#     movl 0x8(%rsi), %ecx  ; len0 (int)
#     movq 0x10(%rsi), %r9  ; ptr1
#     movl 0x18(%rsi), %ecx ; len1
#     ... 4 entries of 16 bytes each: {const uint8_t *ptr; int blocks; int pad}
#   edx = num (max blocks) stored to stack
#
