#include <stdio.h>
#include <stdint.h>
#include <string.h>
#include <stdlib.h>
#include <openssl/sha.h>
#include <time.h>

extern void sha256_multi_block(uint32_t *state /* interleaved? */, void *inp, int num);

typedef struct {
    const uint8_t *ptr;
    int blocks;
    int pad;
} mb_in;

int main() {
    /* 4 independent short messages of exactly 1 block (64 bytes), no padding handled by multi_block
       (it just compresses N blocks). We'll compare against SHA256 of 64 zero-pad? 
       Better: take a long buffer, process nblocks via multi_block on 4 copies, compare state
       against calling SHA256_Transform nblocks times.
    */
    size_t nblocks = 1000;
    uint8_t *data[4];
    for (int i = 0; i < 4; i++) {
        data[i] = aligned_alloc(64, nblocks*64);
        memset(data[i], 0x10+i, nblocks*64);
    }
    /* reference state via openssl transform */
    uint32_t ref[4][8];
    for (int i = 0; i < 4; i++) {
        uint32_t s[8] = {0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19};
