    }

    /* bench */
    size_t big = 20000ul*1024/64; /* blocks */
    for (int i=0;i<4;i++){ free(data[i]); data[i]=aligned_alloc(64, big*64); memset(data[i],0x5a,big*64); }
    for (int w=0;w<8;w++) for(int lane=0;lane<4;lane++) state[w*4+lane]=init[w];
    for (int i=0;i<4;i++){ inp[i].ptr=data[i]; inp[i].blocks=(int)big; inp[i].pad=0; }
    struct timespec t0,t1;
    int iters=5;
    clock_gettime(CLOCK_MONOTONIC,&t0);
    for(int it=0; it<iters; it++){
