#include <gcrypt.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
int main(){
    if (!gcry_check_version("1.10.0")) { printf("gcrypt init fail\n"); return 1; }
    gcry_control(GCRYCTL_DISABLE_SECMEM, 0);
    gcry_control(GCRYCTL_INITIALIZATION_FINISHED, 0);
    size_t n=20000ul*1024;
    unsigned char *data=malloc(n); memset(data,0x5a,n);
    unsigned char out[32];
    gcry_md_hash_buffer(GCRY_MD_SHA256, out, data, n);
    struct timespec t0,t1; int iters=8;
    clock_gettime(CLOCK_MONOTONIC,&t0);
    for(int i=0;i<iters;i++) gcry_md_hash_buffer(GCRY_MD_SHA256, out, data, n);
    clock_gettime(CLOCK_MONOTONIC,&t1);
    double ms=((t1.tv_sec-t0.tv_sec)*1000.0+(t1.tv_nsec-t0.tv_nsec)/1e6)/iters;
    printf("gcrypt: %.2f ms (%.1f MB/s)\n", ms, (n/1e6)/(ms/1000.0));
    for(int i=0;i<32;i++) printf("%02x", out[i]); printf("\n");
    return 0;
}
EOF
